INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (354196, 14823, 'South China Morning Post', 'en', 'Magnitude 5.9 aftershock strikes Indonesia’s Flores as quake death toll rises to 53', 'https://www.scmp.com/news/asia/southeast-asia/article/3364225/magnitude-59-aftershock-strikes-indonesias-flores-quake-death-toll-rises-53', '⁠An ⁠earthquake of magnitude ‌5.9 struck Indonesia’s Flores region ⁠on Monday, the ‌German Research ‌Centre for Geosciences ⁠said, ⁠hitting ‌at a ‌depth ‌of ‌10km (six miles). The aftershock comes two days after a magnitude 7.7 quake shook six regencies on Flores, a predominantly Catholic island in the Muslim-majority country. Rescue teams in eastern Indonesia recovered six more bodies on Sunday, raising the death toll to 53, authorities said, as many of the thousands of displaced people spent...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/17/40cdc2da-35fa-40ae-84cb-8ad47132dfb2_e6c04bec.jpg?itok=YhC7lwlx&v=1786930134', '2026-08-17T01:29:01+00:00', '2026-08-17T01:36:06.522902'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
