INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (349899, 14888, 'BBC News', 'en', 'US commander says mental health a ''priority'' on USS Lincoln', 'https://www.bbc.co.uk/news/articles/ceqeeendz42o', 'Adm Brad Cooper acknowledged that navy service at sea for long periods is "uniquely challenging and tough", following a visit to the warship.', 'https://ichef.bbci.co.uk/ace/standard/240/cpsprodpb/cfe2/live/6ee53b10-99ab-11f1-870d-5d08c49babb2.jpg', '2026-08-16T21:04:27+00:00', '2026-08-16T22:01:45.318478'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (349915, 14888, 'The Guardian', 'en', 'Democrats demand answers from Trump on USS Abraham Lincoln conditions', 'https://www.theguardian.com/us-news/2026/aug/16/democrats-trump-uss-abraham-lincoln', 'Senator Ruben Gallego calls carrier’s months-long deployment a ‘deep problem’ as wellbeing concerns mount Democrats on Sunday intensified their demands for answers from the Trump administration over conditions aboard the USS Abraham Lincoln as the aircraft carrier’s nearly nine-month deployment continued fueling concern over crew morale, mental health and living conditions. Ruben Gallego, a Democratic senator from Arizona, said on Sunday that problems aboard the Lincoln had kept mounting – and he blamed the carrier’s prolonged deployment on the unresolved war that Donald Trump started in Febru', 'https://i.guim.co.uk/img/media/c3cfd24cda3e978ac3cf705221a3ee06cb70e778/483_0_3619_2896/master/3619.jpg?width=140&quality=85&auto=format&fit=max&s=525fc8d40d15f7f52179d96acd71fe89', '2026-08-16T17:08:20+00:00', '2026-08-16T22:01:57.169596'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
