INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (354197, 14888, 'South China Morning Post', 'en', 'USS Lincoln leaders making mental health ‘a priority’ during long deployment: US commander', 'https://www.scmp.com/news/world/united-states-canada/article/3364224/uss-lincoln-leaders-making-mental-health-priority-during-long-deployment-us-commander', 'A top US military commander said mental health was a valid concern after meeting crew deployed on the USS Abraham Lincoln, where conditions aboard the aircraft carrier have led to complaints during its long deployment in the Iran war. Admiral Brad Cooper’s visit to the carrier in the Arabian Sea followed outrage among family members about reports of food shortages, water contamination, mouldy showers and long shifts in wartime aboard the vessel, which has been deployed without a port call for...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/17/542e22c9-62c8-40c8-9ad7-811c91a4f116_4a6c43a7.jpg?itok=RFpL7GOC&v=1786928418', '2026-08-17T01:00:29+00:00', '2026-08-17T01:36:06.541733'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
