INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (349354, 14889, 'Aaj Tak', 'hi', 'अमेरिकी सैनिक पकड़ने पर 30,000 डॉलर का इनाम... ईरान का ऐलान', 'https://www.aajtak.in/world/story/iran-army-commander-amir-hatami-announces-bounty-on-us-soldiers-ntc-apdy-dskc-2623477-2026-08-16', 'ईरानी सेना के कमांडर ने अमेरिकी सैनिकों को पकड़ने या मारने वाले ईरानी लड़ाकों के लिए 30,000 डॉलर के इनाम का ऐलान किया. यह घोषणा ऐसे समय हुई है, जब शांति वार्ता में कोई प्रगति नहीं हुई है और होर्मुज स्ट्रेट से तेल टैंकरों की आवाजाही भी रुकी हुई है.', '', '2026-08-16T17:03:12+00:00', '2026-08-16T21:59:47.975079'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
