INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (351876, 14889, 'South China Morning Post', 'en', 'Iran offers US$30,000 bounty for killing or capturing US soldiers', 'https://www.scmp.com/news/world/middle-east/article/3364216/iran-offers-us30000-bounty-killing-or-capturing-us-soldiers', 'Iran’s military announced on Sunday that it was offering a bounty equivalent to US$30,000 for killing or capturing US soldiers, with the reward doubled if carried out by a woman. Army chief Amir Hatami said the plan had been drawn up following a “large number of requests” to take part, according to the IRNA state news agency. There has been no known deployment of US ground forces in Iran during the Middle East war, with the exception of a rescue mission in April for a downed American...', 'https://cdn.i-scmp.com/sites/default/files/styles/1280x720/public/d8/images/canvas/2026/08/17/a1d64acb-165f-46ab-b71a-58749bc85988_1915fd7f.jpg?itok=oM6NVQla&v=1786900215', '2026-08-16T17:12:43+00:00', '2026-08-16T22:07:41.783915'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
