INSERT INTO public.articles (id, event_id, source, language, title, url, summary, image_url, published, fetched_at) VALUES (349378, 14892, 'Aaj Tak', 'hi', 'दिल्ली मेट्रो में CISF जवान पर लगा फोटो खींचने का आरोप', 'https://www.aajtak.in/short-videos/video/cisf-jawan-suspended-over-alleged-woman-photo-incident-at-aiims-metro-station-departmental-inquiry-begins-mmta-2623456-2026-08-16', 'दिल्ली के एम्स मेट्रो स्टेशन पर सीआईएसएफ के एक जवान पर महिला यात्री की तस्वीरें चुपके से लेने का आरोप लगा है. घटना के बाद सोशल मीडिया पर वीडियो वायरल हुआ और मामले ने तूल पकड़ लिया. सीआईएसएफ ने आरोपी जवान को निलंबित कर विभागीय जांच शुरू कर दी है. हालांकि, मेट्रो पुलिस के मुताबिक महिला ने कोई शिकायत दर्ज नहीं कराई और पिस्टल तानने की बात भी गलत बताई गई है.', '', '2026-08-16T17:12:15+00:00', '2026-08-16T21:59:49.147681'::timestamptz) ON CONFLICT (id) DO UPDATE SET event_id = EXCLUDED.event_id, source = EXCLUDED.source, language = EXCLUDED.language, title = EXCLUDED.title, url = EXCLUDED.url, summary = EXCLUDED.summary, image_url = EXCLUDED.image_url, published = EXCLUDED.published, fetched_at = EXCLUDED.fetched_at;
